$('mix-inputs').innerHTML=CODES.map((c,i)=>(i===0?'<h3 class="mix-group">Established patients</h3>':i===4?'<h3 class="mix-group">New patients</h3>':'')+`<div class="mix-row"><label for="mix-${c}"><b>${c}</b><small>${LABELS[i]}</small></label><div class="percent-input"><input id="mix-${c}" type="number" min="0" max="100" step="1" inputmode="decimal" value="${DEFAULT_MIX[c]}"><span aria-hidden="true">%</span></div></div>`).join('');
function sourceLink(id,page,label){const s=data.sources.find(s=>s.id===id);return s?.url?`<a href="${esc(s.url)}${page?'#page='+page:''}" target="_blank" rel="noopener">${esc(label||s.title||id)} ↗</a>`:esc(id);}
