const apcmPatients=()=>APCM_CODES.reduce((a,c)=>a+(Number.isFinite(state.apcm?.[c])?state.apcm[c]:0),0);
function sync(){syncTrack();for(const k of ['visits','days','complexity'])$(k).value=state[k];$('complexity-number').value=state.complexity;for(const c of CODES)$('mix-'+c).value=state.mix[c];for(const c of APCM_CODES)$('apcm-'+c).value=state.apcm[c];}
function read(){for(const k of ['visits','days'])state[k]=$(k).value===''?NaN:Number($(k).value);for(const c of CODES)state.mix[c]=$('mix-'+c).value===''?NaN:Number($('mix-'+c).value);for(const c of APCM_CODES)state.apcm[c]=$('apcm-'+c).value===''?NaN:Number($('apcm-'+c).value);}
function updateURL(){if(valid&&shared&&!blocked)history.replaceState(null,'','#scenario='+serialize(lastState,view));}
const TRACK_LABELS={'basic-ad':'BASIC A–D','basic-e':'BASIC E',enhanced:'ENHANCED',lead:'LEAD'};
function syncTrack(){
 for(const e of document.querySelectorAll('[name=program]'))e.checked=e.value===state.program;
 for(const e of document.querySelectorAll('[name=track]'))e.checked=e.value===state.track;
 for(const e of document.querySelectorAll('[name=qp]'))e.checked=e.value===(state.qp?'yes':'no');
 $('step-track').hidden=state.program!=='aco';$('step-qp').hidden=state.program==='none';
 let n=1;for(const id of ['step-program','step-track','step-qp'])if(!$(id).hidden)$(id).querySelector('.step-n').textContent=n++;
 const m=modifierFor(state);$('track-result').innerHTML=`<span>Your 2027 pricing</span><strong>${state.qp?'QP':'Non-QP'} rate + ${m} (${m==='B2'?'32%':'16%'})</strong>${state.program==='aco'?`<small>${TRACK_LABELS[state.track]} · B2 applies in every MSSP track and LEAD</small>`:state.program==='apm'?'<small>B2 is limited to MSSP and LEAD</small>':''}`;
}
function render(){const next=calculate(data,state);valid=next.valid&&validYears(view);$('error').hidden=valid;$('error').textContent=next.errors?.join(' ')||(!validYears(view)?'Choose two to four different years.':'');$('stale-note').hidden=valid;for(const id of ['share','export'])$(id).disabled=!valid||blocked;for(const el of document.querySelectorAll('.comparison-table select,.comparison-table button'))el.disabled=!valid||blocked;for(const id of ['change-panel','history-panel','comparison-table'])$(id).classList.toggle('is-stale',!valid);for(const e of document.querySelectorAll('.event-marker,.event-list-item'))e.disabled=!valid;const sum=CODES.reduce((a,c)=>a+(Number.isFinite(state.mix[c])?state.mix[c]:0),0);const off=Math.round((sum-100)*100)/100,bad=Math.abs(off)>.005;$('mix-total').textContent=bad?`${Number(sum.toFixed(2))}% · ${Math.abs(off)}% ${off>0?'over':'under'}`:'Total: 100%';$('mix-total').classList.toggle('invalid',bad);$('balance-box').hidden=!bad||sum<=0;$('practice-summary').textContent=`${state.qp?'QP':'Non-QP'} + ${modifierFor(state)} · ${Number.isFinite(state.visits*state.days)?(state.visits*state.days).toLocaleString('en-US',{maximumFractionDigits:1}):'—'} visits/month · ${Number.isFinite(state.complexity)?state.complexity:'—'}% complexity${apcmPatients()>0?` · ${apcmPatients().toLocaleString('en-US')} APCM/month`:''}`;$('apcm-total').textContent=apcmPatients()>0?`${apcmPatients().toLocaleString('en-US')} patients/month`:'None';$('complexity-note').textContent=`Share of office visits billed for complexity: G2211 in 2024–26, ${modifierFor(state)} in 2027.`;if(!valid){expose();return;}result=next;lastState=structuredClone(state);points=monthlySeries(result);events=significantEvents(data,state);renderChange();renderChart();renderTable();updateURL();expose();window.PAYMENT_READY=true;announce('Monthly payments updated for your practice.');}
const signed=n=>(Math.round(n)>0?'+':Math.round(n)<0?'−':'')+money(Math.abs(n)),pctText=n=>n===null||!Number.isFinite(n)?'—':(n>0.00005?'+':n<-0.00005?'−':'')+Math.abs(n*100).toFixed(1)+'%';
function renderChange(){
 const b=changeBreakdown(data,state);if(!b)return;const {from:f,to:t}=b,m=b.modifier,r99214=y=>y.rows.find(r=>r.code==='99214');
 const row=(label,note,a,z,delta,pct,cls='')=>`<tr class="${cls}"><th scope="row">${label}${note?`<small>${note}</small>`:''}</th><td>${money(a)}</td><td>${money(z)}</td><td>${signed(delta)}${pct!==undefined?`<small>${pctText(pct)}</small>`:''}</td></tr>`;
 const driver=(label,note,v)=>`<li><span><b>${label}</b><small>${note}</small></span><strong class="${Math.round(v)<0?'down':Math.round(v)>0?'up':''}">${signed(v)}</strong></li>`;
 $('change-content').innerHTML=`<p class="change-headline"><strong>${signed(b.total)}</strong> a month <span>(${pctText(b.totalPct)}) in 2027 vs 2026, before inflation</span></p>
 <div class="change-table"><table><caption class="sr-only">Monthly payment, 2026 and 2027</caption><thead><tr><th scope="col">Monthly</th><th scope="col">2026</th><th scope="col">2027</th><th scope="col">Change</th></tr></thead><tbody>
 ${row('Visit fees','Office E/M codes',f.baseMonthly,t.baseMonthly,t.baseMonthly-f.baseMonthly)}
 ${row('Complexity add-on',`G2211 → ${m}`,f.complexityMonthly,t.complexityMonthly,t.complexityMonthly-f.complexityMonthly)}
 ${f.apcmMonthly||t.apcmMonthly?row('APCM','Monthly care management',f.apcmMonthly,t.apcmMonthly,t.apcmMonthly-f.apcmMonthly):''}
 ${row('Total','That year’s dollars',f.nominalMonthly,t.nominalMonthly,b.total,b.totalPct,'total')}
 ${['CPI','MEI'].map(k=>row(`${k}-adjusted`,`2026 in 2027 dollars (+${(b.inflation[k].rate*100).toFixed(1)}%)`,b.inflation[k].from,t.nominalMonthly,b.inflation[k].change,b.inflation[k].pct,k)).join('')}
 </tbody></table></div>
 <h3 class="driver-title">What drove the change</h3><ul class="drivers">
 ${driver('2026’s one-time 2.5% increase expires',`Conversion factor $${b.cf.from.toFixed(4)} → $${b.cf.withoutIncrease.toFixed(4)} per RVU (${pctText(b.cf.expiry)})`,b.parts.oneYearIncreaseExpires)}
 ${driver('2027 conversion factor update',`${state.qp?'+0.75% QP':'+0.25% non-QP'} update and −0.12% budget neutrality: $${b.cf.withoutIncrease.toFixed(4)} → $${b.cf.to.toFixed(4)} (${pctText(b.cf.update)})`,b.parts.cfUpdate)}
 ${driver('Office visit RVUs revalued',b.parts.revaluation<-.5?'Lower 2027 RVUs for your visit mix, mostly practice expense; work RVUs unchanged':b.parts.revaluation>.5?'Higher 2027 RVUs for your visit mix; work RVUs unchanged':'Little change for your visit mix',b.parts.revaluation)}
 ${driver(`G2211 → ${m}`,`Fixed add-on replaced by ${m==='B2'?'32%':'16%'} of the visit fee`,b.parts.coding)}
 ${Math.abs(b.parts.apcm)>.5?driver('APCM rate change','Same patients; 2027 APCM RVUs and conversion factor',b.parts.apcm):''}
 ${Math.abs(b.parts.sequestration)>.5?driver('Sequestration rate change','Change in the cut to Medicare’s share',b.parts.sequestration):''}
 </ul>
 <h3 class="driver-title">All four combinations</h3><div class="change-table combo-table"><table><caption class="sr-only">2026 to 2027 monthly change for each conversion-factor rate and complexity modifier</caption><thead><tr><th scope="col">Rate + modifier</th><th scope="col">2026</th><th scope="col">2027</th><th scope="col">Change</th></tr></thead><tbody>${[[false,false],[true,false],[false,true],[true,true]].map(([qp,b2])=>{const c=changeBreakdown(data,comboState(state,qp,b2)),mine=qp===state.qp&&b2===(m==='B2');return `<tr class="${mine?'mine':''}"><th scope="row">${qp?'QP':'Non-QP'} + ${b2?'B2':'B1'}${mine?'<small>Your answers</small>':''}</th><td>${money(c.from.nominalMonthly)}</td><td>${money(c.to.nominalMonthly)}</td><td>${signed(c.total)}<small>${pctText(c.totalPct)}</small></td></tr>`;}).join('')}</tbody></table></div>
 <details class="disclosure change-help"><summary>Why does ${m} change the add-on?</summary><p>G2211 had its own RVUs and added the same amount to every visit: $${r99214(f).increment.toFixed(2)} on a 99214 in 2026. In 2027, ${m} adds ${m==='B2'?'32%':'16%'} of the base visit’s total RVUs, its full fee: $${r99214(t).increment.toFixed(2)} on a 99214. Higher-level visits gain more and lower-level visits gain less. B2 (32%) is open only to clinicians in an MSSP or LEAD ACO.</p></details>`;
}
const hiddenEvents=new Set(),CATEGORY_NAMES={rate:'Payment rate',rvu:'RVU values',coding:'Coding changes'};
function syncRange(){const {from,to}=view.chart;$('chart-from').innerHTML=YEARS.map(y=>`<option value="${y}"${y===from?' selected':''}${y>=to?' disabled':''}>${y}</option>`).join('');$('chart-to').innerHTML=YEARS.map(y=>`<option value="${y}"${y===to?' selected':''}${y<=from?' disabled':''}>${y}</option>`).join('');}
